test('all runtime, images, fonts, palette generator, fixtures and existing workflows are byte-exact outside the grid and pinned test bridges',()=>{const names=execFileSync('git',['ls-tree','-r','--name-only',s.base],{encoding:'utf8'}).trim().split('\n').filter(f=>/^(nomad360_|portfolio_v2_).*\.(js|css)$/.test(f)||['Marketing_calc.HTML','US_Retail_Demo.HTML','scripts/localization/inventory.cjs'].includes(f)||/^(assets\/|vendor\/|tests\/fixtures\/|\.github\/workflows\/|scripts\/partners\/|scripts\/palette\/|scripts\/cleanup|scripts\/style-ownership\/)/.test(f));for(const name of names){const before=execFileSync('git',['show',s.base+':'+name],{maxBuffer:24e6});A.deepEqual(s.restore(name,fs.readFileSync(path.join(s.root,name))),before,name);}});

test('historical C5-4 and C5-6 census remain explicitly separate',()=>{const dir=fs.mkdtempSync(path.join(require('node:os').tmpdir(),'c56-census-'));try{for(const [script,file]of [['scripts/cleanup-about-copy/ownership.cjs','historical.json'],['scripts/cleanup-payment-grid/ownership.cjs','current.json']])execFileSync(process.execPath,[script,path.join(dir,file)],{cwd:s.root});const historical=JSON.parse(fs.readFileSync(path.join(dir,'historical.json'))),current=JSON.parse(fs.readFileSync(path.join(dir,'current.json')));A.equal(historical.totalAfter,185);A.match(historical.sourceNormalization,/Historical C5-4/);A.match(current.sourceNormalization,/Historical C5-6/);A.equal(current.rawAfter,183);A.equal(current.unreviewed,164);}finally{fs.rmSync(dir,{recursive:true,force:true});}});
